        seq.make_infinite();
    }
    seq.seq
}

fn extract(&self, hir: &Hir) -> TSeq {
    use regex_syntax::hir::HirKind::*;

    match *hir.kind() {
        Empty | Look(_) => TSeq::singleton(hir::literal::Literal::exact(vec![])),
        Literal(hir::Literal(ref bytes)) => {
